package com.example.business.client;
import com.example.business.config.MailNotificationProperties; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Component; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Duration; import java.time.Instant;
@Component public class InternalMailClient { private final MailNotificationProperties props; private final ObjectMapper json; private final HttpClient http; public InternalMailClient(MailNotificationProperties props,ObjectMapper json){this.props=props;this.json=json;this.http=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(props.connectTimeoutMs())).build();} public int post(Object event,String eventId) throws Exception { if(!validSecret()) throw new IllegalStateException("internal mail HMAC secret unavailable"); byte[] body=json.writeValueAsBytes(event); long ts=Instant.now().getEpochSecond(); HttpRequest request=HttpRequest.newBuilder(URI.create(props.baseUrl()+"/internal/mail/order-created")).timeout(Duration.ofMillis(props.readTimeoutMs())).header("Content-Type","application/json").header("X-Internal-Event-Id",eventId).header("X-Internal-Timestamp",Long.toString(ts)).header("X-Internal-Signature",sign(ts,eventId,body)).POST(HttpRequest.BodyPublishers.ofByteArray(body)).build(); return http.send(request,HttpResponse.BodyHandlers.discarding()).statusCode(); } public boolean validSecret(){return props.hmacSecret()!=null&&props.hmacSecret().trim().getBytes(StandardCharsets.UTF_8).length>=32;} private String sign(long ts,String id,byte[] body) throws Exception {String payload=ts+"\n"+id+"\n"+java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(body));Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(props.hmacSecret().trim().getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return java.util.HexFormat.of().formatHex(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));} }
